class RandomizedSet:
    def __init__(self):
        self.vals=[];self.mp={}
    def insert(self,val):
        if val in self.mp: return False
        self.mp[val]=len(self.vals);self.vals.append(val);return True
    def remove(self,val):
        if val not in self.mp: return False
        i=self.mp[val];last=self.vals[-1]
        self.vals[i]=last;self.mp[last]=i
        self.vals.pop();del self.mp[val];return True
    def getRandom(self):
        return random.choice(self.vals)

