def trap(height):
    l,r=0,len(height)-1;lm=rm=water=0
    while l<r:
        if height[l]<height[r]:
            if height[l]>=lm: lm=height[l]
            else: water+=lm-height[l]
            l+=1
        else:
            if height[r]>=rm: rm=height[r]
