def shortestPath(n,edges,src):
    adj=[[] for _ in range(n)]
    for u,v,w in edges: adj[u].append((v,w))
    dist=[float('inf')]*n;dist[src]=0
    heap=[(0,src)]
    while heap:
        d,u=heapq.heappop(heap)
        if d>dist[u]: continue
        for v,w in adj[u]:
            if d+w<dist[v]:
                dist[v]=d+w;heapq.heappush(heap,(dist[v],v))
    return dist

