def longestPalindrome(s):
    best = (0, 0)
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1
    for i in range(len(s)):
        for l, r in ((i, i), (i, i + 1)):
            a, b = expand(l, r)
            if b - a > best[1] - best[0]:
                best = (a, b)
    return s[best[0]:best[1] + 1]

