import sys

class DSU:
    def __init__(self):
        self.parent = {}
    def find(self, x):
        if x not in self.parent:
            self.parent[x] = x
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        self.parent[px] = py

def main():
    data = sys.stdin.read().strip()
    equations = eval(data.split("=", 1)[1].strip())
    dsu = DSU()
    for eq in equations:
        if eq[1] == '=':
            dsu.union(eq[0], eq[3])
    for eq in equations:
        if eq[1] == '!':
            if dsu.find(eq[0]) == dsu.find(eq[3]):
                print("false")
                return
    print("true")

main()
